public class Solution {
    public static void main(String[] args) throws InterruptedException {
        StringBuffer buffer = new StringBuffer();
        StringBuilder builder = new StringBuilder();

        Thread[] threadsBuf = new Thread[2];
        Thread[] threadsBld = new Thread[2];

        for (int i = 0; i < 2; i++) {
            threadsBuf[i] = new Thread(() -> {
                for (int j = 0; j < 1000; j++) buffer.append("A");
            });
            threadsBld[i] = new Thread(() -> {
                for (int j = 0; j < 1000; j++) builder.append("A");
            });
            threadsBuf[i].start();
            threadsBld[i].start();
        }

        for (int i = 0; i < 2; i++) {
            threadsBuf[i].join();
            threadsBld[i].join();
        }

        System.out.println("Expected total characters: 2000");
        System.out.println("StringBuffer final length (thread-safe): " + buffer.length());
        System.out.println("StringBuilder race condition detected: " + (builder.length() <= 2000));
    }
}

public class Solution {
    public static void appendInt(StringBuilder sb, int num) {
        if (num == 0) {
            sb.append('0');
            return;
        }
        if (num < 0) {
            sb.append('-');
            num = -num;
        }
        StringBuilder temp = new StringBuilder();
        while (num > 0) {
            int digit = num % 10;
            temp.append((char) ('0' + digit));
            num /= 10;
        }
        sb.append(temp.reverse());
    }

    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder("Processed Count: ");
        appendInt(sb, 4289);
        System.out.println(sb.toString());
    }
}

public class Solution {
    public static void removeDuplicates(StringBuilder sb) {
        for (int i = 0; i < sb.length(); i++) {
            char current = sb.charAt(i);
            for (int j = 0; j < i; j++) {
                if (sb.charAt(j) == current) {
                    sb.deleteCharAt(i);
                    i--; // Adjust index after shift
                    break;
                }
            }
        }
    }

    public static void main(String[] args) {
        StringBuilder buffer = new StringBuilder("banana_apple");
        System.out.println("Before: " + buffer.toString());
        removeDuplicates(buffer);
        System.out.println("After:  " + buffer.toString());
    }
}

public class Solution {
    public static String encodeRLE(String text) {
        if (text == null || text.isEmpty()) return "";
        StringBuilder sb = new StringBuilder(text.length());
        int count = 1;
        for (int i = 1; i < text.length(); i++) {
            if (text.charAt(i) == text.charAt(i - 1)) {
                count++;
            } else {
                sb.append(text.charAt(i - 1)).append(count);
                count = 1;
            }
        }
        sb.append(text.charAt(text.length() - 1)).append(count);
        return sb.toString();
    }

    public static void main(String[] args) {
        String source = "AAAAABBBCCDAA";
        String encoded = encodeRLE(source);
        System.out.println("Source:  " + source);
        System.out.println("Encoded: " + encoded);
    }
}

public class Solution {
    public static String escapeHtml(String text) {
        if (text == null) return "";
        StringBuilder sb = new StringBuilder(text.length() + 16);
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            switch (c) {
                case '<'  -> sb.append("&lt;");
                case '>'  -> sb.append("&gt;");
                case '&'  -> sb.append("&amp;");
                case '"' -> sb.append("&quot;");
                case '\'' -> sb.append("&#39;");
                default   -> sb.append(c);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String rawHtml = "<script>alert('User & Admin');</script>";
        String escaped = escapeHtml(rawHtml);
        System.out.println("Escaped HTML: " + escaped);
    }
}

