public class Solution {
    static class CustomBuffer {
        private char[] value;
        private int count;

        public CustomBuffer() {
            this(16);
        }

        public CustomBuffer(int capacity) {
            value = new char[capacity];
            count = 0;
        }

        public CustomBuffer append(String str) {
            if (str == null) str = "null";
            int len = str.length();
            ensureCapacity(count + len);
            str.getChars(0, len, value, count);
            count += len;
            return this;
        }

        private void ensureCapacity(int minCapacity) {
            if (minCapacity > value.length) {
                int newCap = (value.length * 2) + 2;
                if (newCap < minCapacity) newCap = minCapacity;
                char[] newArr = new char[newCap];
                System.arraycopy(value, 0, newArr, 0, count);
                value = newArr;
            }
        }

        public String toString() {
            return new String(value, 0, count);
        }
    }

    public static void main(String[] args) {
        CustomBuffer cb = new CustomBuffer(4);
        cb.append("Hello").append(" ").append("Custom").append(" ").append("Buffer!");
        System.out.println(cb.toString());
    }
}

public class Solution {
    private static final ThreadLocal<StringBuilder> BUFFER_HOLDER = 
        ThreadLocal.withInitial(() -> new StringBuilder(256));

    public static String formatLog(String level, String msg) {
        StringBuilder sb = BUFFER_HOLDER.get();
        sb.setLength(0); // Reset buffer in place for zero-allocation reuse
        sb.append("[").append(level).append("] ")
          .append("[").append(Thread.currentThread().getName()).append("] ")
          .append(msg);
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(formatLog("INFO", "Service ready."));
        System.out.println(formatLog("WARN", "Cache threshold near limit."));
    }
}

public class Solution {
    public static String addLargeNumbers(String num1, String num2) {
        StringBuilder result = new StringBuilder();
        int i = num1.length() - 1;
        int j = num2.length() - 1;
        int carry = 0;

        while (i >= 0 || j >= 0 || carry > 0) {
            int digit1 = (i >= 0) ? num1.charAt(i--) - '0' : 0;
            int digit2 = (j >= 0) ? num2.charAt(j--) - '0' : 0;
            int total = digit1 + digit2 + carry;
            result.append(total % 10);
            carry = total / 10;
        }

        return result.reverse().toString();
    }

    public static void main(String[] args) {
        String n1 = "99999999999999999999";
        String n2 = "1";
        System.out.println("Sum: " + addLargeNumbers(n1, n2));
    }
}

public class Solution {
    public static String stripMarkdown(String md) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        int len = md.length();

        while (i < len) {
            if (i + 1 < len && md.charAt(i) == '*' && md.charAt(i + 1) == '*') {
                i += 2; // Skip bold marker
            } else if (md.charAt(i) == '_' || md.charAt(i) == '*') {
                i++; // Skip italic marker
            } else if (md.charAt(i) == '[') {
                int closeBracket = md.indexOf(']', i);
                int openParen = md.indexOf('(', closeBracket);
                int closeParen = md.indexOf(')', openParen);
                if (closeBracket != -1 && openParen == closeBracket + 1 && closeParen != -1) {
                    sb.append(md, i + 1, closeBracket);
                    i = closeParen + 1;
                } else {
                    sb.append(md.charAt(i++));
                }
            } else {
                sb.append(md.charAt(i++));
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String md = "Read **Java Guide** and visit [Oracle](https://oracle.com) today!";
        System.out.println("Plaintext: " + stripMarkdown(md));
    }
}

import java.util.function.Consumer;

public class Solution {
    static class ZeroGarbageTokenizer {
        private final StringBuilder tokenBuffer = new StringBuilder(64);

        public void tokenize(String text, char delimiter, Consumer<CharSequence> consumer) {
            tokenBuffer.setLength(0);
            for (int i = 0; i < text.length(); i++) {
                char c = text.charAt(i);
                if (c == delimiter) {
                    consumer.accept(tokenBuffer);
                    tokenBuffer.setLength(0); // Reset for zero-allocation reuse
                } else {
                    tokenBuffer.append(c);
                }
            }
            consumer.accept(tokenBuffer);
        }
    }

    public static void main(String[] args) {
        ZeroGarbageTokenizer tokenizer = new ZeroGarbageTokenizer();
        String streamData = "ORD101|PAY500|SHP99";

        System.out.println("Stream Tokens:");
        tokenizer.tokenize(streamData, '|', token -> System.out.println("Token: " + token));
    }
}
